App.route('brand-kit',()=>{const k=ST.brandKit;return `
  <div class="page-head"><div><h1>AI Brand Kit</h1><p class="sub">Choose a source and we'll pull out your colours, fonts and tone – then use them on every menu, email and post.</p></div></div>
  ${k?`<div class="card pad" style="margin-bottom:24px;display:flex;gap:18px;align-items:center;flex-wrap:wrap"><div><div class="eyebrow">Your brand kit</div><h2 style="margin-top:4px">${esc(k.name)}</h2>${k.tagline?`<div class="muted">${esc(k.tagline)}</div>`:''}</div>
   <div style="display:flex;gap:6px">${Object.values(k.colors).map(c=>`<span class="swatch" style="background:${c}" title="${c}"></span>`).join('')}</div>
   <div><div class="help" style="margin:0">Typography</div><strong style="color:var(--ink)">${esc(k.typeName)}</strong></div><div><div class="help" style="margin:0">Imagery</div><strong style="color:var(--ink)">${esc(k.mood)}</strong></div>
   <div style="margin-left:auto"><button class="btn secondary" data-action="ai-bk-edit">${ic('edit','sm')}Edit</button></div></div>`:''}
  <div class="card ai-border" style="padding:26px;display:grid;grid-template-columns:1fr auto;gap:20px;align-items:center;margin-bottom:16px">
   <div><div style="display:flex;gap:8px;margin-bottom:10px"><span class="pill">★ RECOMMENDED</span><span class="pill grey">${ic('clock','sm')}40 sec</span></div><h2>Upload menu file or photo</h2><p class="muted" style="margin:6px 0 0">PDF, JPG or PNG · pulls colours, fonts, dishes and prices – the most accurate option</p></div>
   <label class="btn primary" style="cursor:pointer">Choose menu file ${ic('chev','sm')}<input type="file" accept=".pdf,image/*" style="display:none" data-change="ai-bk-file" data-src="menu"></label></div>
  <div class="grid g2" style="margin-bottom:22px">
   ${[['Upload brand guideline','30 sec','PDF · straight from your brand book','.pdf','guide','book'],['Upload your logo','15 sec','PNG, SVG or JPG · colours only','image/*,.svg','logo','img']].map(([t,s,d,acc,src,i])=>`<label class="card pad" style="display:flex;gap:14px;align-items:center;cursor:pointer"><span class="itile">${ic(i)}</span><div style="flex:1"><div style="display:flex;gap:8px;align-items:center"><h3>${t}</h3><span class="pill grey">${ic('clock','sm')}${s}</span></div><div class="help">${d}</div></div>${ic('chev')}<input type="file" accept="${acc}" style="display:none" data-change="ai-bk-file" data-src="${src}"></label>`).join('')}
  </div>
  <p style="text-align:center" class="muted">Have nothing yet? <a href="#brand-kit-scratch" data-action="ai-bk-new"><strong>Build a kit from scratch</strong></a></p>`});
A('ai-bk-file',el=>{const f=el.files[0];if(!f)return;const src=el.dataset.src;el.value='';
  modal({title:'Extracting your brand…',body:`<div style="display:flex;gap:12px;align-items:center"><span class="itile ai-grad" style="color:#fff">${ic('sparkle')}</span><div><strong style="color:var(--ink)">${esc(f.name)}</strong><div class="help" style="margin:0">Reading colours, fonts${src==='logo'?'':' and tone'}…</div></div></div><div class="progress" style="margin-top:16px"><i id="bkBar" style="width:5%;transition:width 1.6s"></i></div>`});
  setTimeout(()=>{const b=$('#bkBar');if(b)b.style.width='100%'},50);
  setTimeout(()=>{const pal=[['primary','#B23A2E'],['secondary','#E8B04B'],['accent','#2F6B4F'],['background','#FFFAF3'],['surface','#F4ECE0'],['ink','#2B1D16']];App._bkExtract={pal,src};
   modal({title:'Here\'s what we found',body:`<div class="help" style="margin-top:0">From ${esc(f.name)}</div><div style="display:flex;gap:8px;margin:12px 0 18px">${pal.map(([k,c])=>`<div style="text-align:center"><span class="swatch" style="display:block;width:54px;height:54px;background:${c}"></span><small class="muted">${k}</small></div>`).join('')}</div>
    <div class="stat-row"><span>Fonts</span><strong style="color:var(--ink)">${src==='logo'?'Not detected':'Recoleta + Manrope'}</strong></div><div class="stat-row"><span>Tone</span><strong style="color:var(--ink)">${src==='logo'?'—':'Warm, homely, generous'}</strong></div>${src==='menu'?`<div class="stat-row"><span>Dishes found</span><strong style="color:var(--ink)">${allItems().length}</strong></div>`:''}`,
    footer:`<button class="btn secondary" data-action="ai-bk-new" data-href="brand-kit-scratch">Fine-tune</button><button class="btn primary" data-action="ai-bk-apply">Apply</button>`})},1800)});
A('ai-bk-apply',()=>{const p=Object.fromEntries(App._bkExtract.pal);ST.brandKit={name:ST.venue.name,tagline:'',colors:p,typeName:App._bkExtract.src==='logo'?'Urbanist + Inter':'Recoleta + Manrope',mood:'Rustic'};closeModal();App.render();toast('Brand kit applied')});

/* wizard */
const BK_STEPS=['Identity','Logo','Colors','Typography','Imagery','Review & create'];
const PRESETS={'Neon Tokyo':['#FF2E88','#00E5FF','#FFE600','#0B0B1A','#16163A','#F5F5FF'],'Coastal':['#1F7A8C','#BFDBF7','#E1A140','#FFFFFF','#F1F7FA','#14213D'],'Heritage':['#7B2D26','#D4A373','#2F5233','#FFFBF4','#F3EAD8','#2B1D16'],'Matcha':['#5A7D3A','#C7D9A8','#D97D54','#FBFBF4','#EEF2E2','#1F2A16'],
 'Noir':['#111111','#555555','#C9A227','#FFFFFF','#F2F2F2','#0A0A0A'],'Street':['#FF5722','#212121','#FFC107','#FFFFFF','#F5F5F5','#121212'],'Warm neutral':['#A47551','#D8C3A5','#8E8D8A','#FBF8F3','#F2EBE0','#3A2E25'],'Deep green':['#1B4332','#95D5B2','#D4A373','#FFFFFF','#F1F6F3','#0B1F17'],
 'Terracotta':['#C65D3B','#F2CC8F','#3D405B','#FFF9F2','#F7EBDD','#2A1C14'],'Mono':['#222222','#888888','#222222','#FFFFFF','#F5F5F5','#111111'],'Pastel':['#E09FB0','#A8D8EA','#FFD3B6','#FFFDF9','#FBF1F3','#3B3355'],'Jewel':['#5B2A86','#1B998B','#E7B10A','#FFFFFF','#F5F1FA','#1E1033']};
const ROLES=[['primary','Primary','Menu: buttons, active tabs, prices, links, selected options · Website: buttons, prices, icons, link hover · Instagram: main colour'],['secondary','Secondary','Not used on the menu or website · Instagram: supporting colour'],['accent','Accent','Menu: "Required" and "Default" badges · Website: review stars'],['background','Background','Menu: page, item cards, pop-up sheets · Website: page, header, cards'],['surface','Surface','Menu: list page, cart · Website: alternating bands, dropdowns'],['ink','Ink','Text colour. Also drives the derived tokens below']];
const TYPES=[['URBANIST + INTER','Clean · modern','Urbanist + Inter','800','400'],['FRAUNCES + INTER','Editorial · warm','Fraunces + Inter','600','400'],['PP EDITORIAL + SÖHNE','Luxe · serif','PP Editorial + Söhne','400','400'],['RECOLETA + MANROPE','Heritage · friendly','Recoleta + Manrope','700','500'],['SPACE GROTESK + IBM PLEX SANS','Bold · contemporary','Space Grotesk + IBM Plex Sans','700','400']];
const TYPE_FAM=['system-ui,sans-serif','Georgia,serif','"Times New Roman",serif','Georgia,serif','ui-monospace,monospace'];
const MOODS=[['Rustic','Wood, cast iron, candlelight'],['Modern','Clean lines, negative space'],['Luxe','Marble, brass, low-key lighting'],['Vibrant','Saturated, energetic, street'],['Coastal','Sun-bleached, airy, oceanic'],['Craft','Hands at work, raw ingredients']];
let BK=null;
function bkNew(from){const k=from||{};BK={step:0,name:k.name||ST.venue.name,tagline:k.tagline||'',cuisine:k.cuisine||'',concept:k.concept||'',logo:k.logo||null,preset:k.preset||'Custom',
  colors:{...(k.colors||{primary:'#1565C0',secondary:'#E8F1FC',accent:'#E8A317',background:'#FFFFFF',surface:'#F5F7FA',ink:'#1A2330'})},type:k.type??0,mood:k.mood||'Modern'}}
A('ai-bk-new',()=>{bkNew();closeModal()});
A('ai-bk-edit',()=>{bkNew(ST.brandKit);App.go('brand-kit-scratch')});
function lum(hex){const c=hex.replace('#','');const v=[0,2,4].map(i=>parseInt(c.substr(i,2),16)/255).map(x=>x<=.03928?x/12.92:Math.pow((x+.055)/1.055,2.4));return .2126*v[0]+.7152*v[1]+.0722*v[2]}
const contrast=(a,b)=>{const x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)};
function bkSample(){const c=BK.colors;return `<div style="background:${c.background};border:1px solid var(--border);border-radius:14px;padding:18px;color:${c.ink}"><div style="display:flex;justify-content:space-between;align-items:center"><span style="font-size:12px;font-weight:700;letter-spacing:.06em;color:${c.primary}">${esc(BK.name.toUpperCase())}</span><span style="background:${c.accent};color:${contrast(c.accent,'#ffffff')>contrast(c.accent,'#000000')?'#fff':'#000'};font-size:11px;font-weight:700;padding:2px 8px;border-radius:999px">New</span></div>
  <h3 style="color:${c.ink};margin:10px 0 4px;font-size:20px">Tonight's tasting menu</h3><p style="margin:0 0 12px;opacity:.85">Six courses, all sourced within fifty miles. Bookings open Thursday.</p>
  <div style="background:${c.surface};border-radius:10px;padding:10px 12px;display:flex;justify-content:space-between;margin-bottom:12px"><span>Six-course menu</span><strong style="color:${c.primary}">£65.00</strong></div>
  <span style="display:inline-block;background:${c.primary};color:${contrast(c.primary,'#ffffff')>=3?'#fff':'#000'};padding:9px 16px;border-radius:10px;font-weight:600">Book a table</span> <span style="display:inline-block;border:1px solid ${c.secondary};padding:8px 14px;border-radius:10px;color:${c.ink}">View menu</span></div>`}
function bkStep(){const s=BK.step,c=BK.colors;
  if(s===0)return `<h2>Identity</h2><p class="muted">Tell us who you are. Everything stays editable later.</p>
   ${UI.field({label:'Restaurant name',control:UI.input({value:BK.name,attrs:'data-input="ai-bk-f" data-k="name"'})})}
   ${UI.field({label:'Tagline',control:UI.input({value:BK.tagline,placeholder:'e.g. Breakfast like home',attrs:'data-input="ai-bk-f" data-k="tagline"'})})}
   ${UI.field({label:'Cuisine',help:'We use it to suggest colours, fonts and a photo mood that suit your food.',control:UI.input({value:BK.cuisine,placeholder:'e.g. Burgers, Sushi, Coffee',attrs:'data-input="ai-bk-f" data-k="cuisine"'})})}
   ${UI.field({label:'Concept',help:'2–3 sentences – helps AI tune everything else.',control:UI.textarea({value:BK.concept,rows:4,attrs:'data-input="ai-bk-f" data-k="concept"'})})}`;
  if(s===1)return `<h2>Logo</h2><p class="muted">PNG, JPG or WEBP – or skip to use a wordmark placeholder.</p>
   <label class="upload ${BK.logo?'done':''}" style="padding:36px">${ic('upload')}<div style="font-weight:600;margin-top:6px">${BK.logo?esc(BK.logo):'Upload your logo'}</div><div class="help">PNG, JPG or WEBP</div><input type="file" accept=".png,.jpg,.jpeg,.webp" style="display:none" data-change="ai-bk-logo"></label>
   ${BK.logo?`<button class="btn ghost sm" style="margin-top:8px" data-action="ai-bk-logo-rm">${ic('trash','sm')}Remove</button>`:''}
   <div class="card pad" style="margin-top:16px;text-align:center"><div class="help" style="margin-top:0">Preview</div><div style="font-size:26px;font-weight:800;color:${c.primary}">${BK.logo?ic('img')+' ':''}${esc(BK.name)}</div></div>`;
  if(s===2){const cr=contrast(c.ink,c.background);return `<h2>Colors</h2><p class="muted">See your colours on a live sample as you choose them.</p>
   <div id="bkSample" style="margin:14px 0 18px">${bkSample()}</div>
   <strong style="color:var(--ink)">Start from a preset</strong><div style="display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 20px">${Object.keys(PRESETS).map(p=>`<button class="chip-btn ${BK.preset===p?'on':''}" data-action="ai-bk-preset" data-p="${p}"><span style="display:inline-flex">${PRESETS[p].slice(0,3).map(x=>`<i style="width:10px;height:10px;border-radius:50%;background:${x};display:inline-block;margin-right:-2px;border:1px solid #fff"></i>`).join('')}</span>${p}</button>`).join('')}</div>
   <strong style="color:var(--ink)">Or set each color yourself</strong>
   <div style="margin-top:8px">${ROLES.map(([k,l,u])=>`<div class="form-row" style="align-items:center"><span class="swatch" id="sw-${k}" style="background:${c[k]}"></span><div class="txt"><strong>${l} <span class="muted" style="font-weight:500" id="hx-${k}">${c[k].toUpperCase()}</span></strong><small>${u}</small>${k==='ink'?`<small id="bkCr" style="color:${cr>=4.5?'var(--ok)':'var(--bad)'};font-weight:600">${cr>=7?'Easy to read':cr>=4.5?'Readable':'Hard to read'} · ${cr.toFixed(1)}:1</small>`:''}</div>
    <label class="btn secondary sm" style="position:relative;cursor:pointer">Change<input type="color" value="${c[k]}" data-input="ai-bk-color" data-k="${k}" style="position:absolute;inset:0;opacity:0;cursor:pointer"></label></div>`).join('')}</div>`}
  if(s===3)return `<h2>Typography</h2><p class="muted">Choose a type pairing</p><div class="grid" style="gap:10px">${TYPES.map((t,i)=>`<button class="select-card ${BK.type===i?'on':''}" data-pick data-action="ai-bk-type" data-i="${i}"><div style="font-family:${TYPE_FAM[i]};font-weight:${t[3]};font-size:22px;color:var(--ink)">${esc(BK.name)}</div><div style="font-weight:${t[4]};margin:4px 0 8px">Seasonal plates, proper coffee and a table that's always ready for one more.</div><span class="eyebrow">${t[0]}</span> <small class="muted">· ${t[1]}</small></button>`).join('')}</div>`;
  if(s===4)return `<h2>Imagery</h2><p class="muted">Imagery mood – sets the look of the photos and campaign visuals AI creates for your brand.</p><div class="grid g3" style="gap:12px">${MOODS.map(([m,d],i)=>`<button class="select-card ${BK.mood===m?'on':''}" data-pick data-action="ai-bk-mood" data-m="${m}" style="padding:0;overflow:hidden">${tile('mood'+m,110,'','border-radius:0')}<div style="padding:12px"><strong style="color:var(--ink)">${m}</strong><div class="help" style="margin:2px 0 0">${d}</div></div></button>`).join('')}</div>`;
  const ok=(t,st,go,extra='')=>`<div class="form-row" style="align-items:center"><div class="txt"><strong>${t}</strong><small>${extra}</small></div>${st}<button class="btn ghost sm" data-action="ai-bk-step" data-i="${go}">${go===1&&!BK.logo?'Add logo':'Edit'}</button></div>`;
  return `<h2>Review & create</h2><p class="muted">Check everything before we build your kit.</p>
   ${ok('Identity',UI.pill('✓ Complete','ok'),0,esc(BK.name)+(BK.cuisine?' · '+esc(BK.cuisine):''))}
   ${ok('Logo',BK.logo?UI.pill('✓ Added','ok'):UI.pill('Skipped','grey'),1,BK.logo?esc(BK.logo):'No logo yet: your name is shown as text until you add one')}
   ${ok('Colors',UI.pill('✓ '+(BK.preset==='Custom'?'Custom':BK.preset),'ok'),2,`<span style="display:inline-flex;gap:4px;margin-top:4px">${Object.values(c).map(x=>`<i style="width:16px;height:16px;border-radius:4px;background:${x};border:1px solid var(--border);display:inline-block"></i>`).join('')}</span>`)}
   ${ok('Typography',UI.pill('✓ '+TYPES[BK.type][2],'ok'),3)}
   ${ok('Imagery',UI.pill('✓ '+BK.mood,'ok'),4)}
   <div class="card pad" style="background:var(--brand-tint-subtle);margin-top:14px;display:flex;gap:10px">${ic('info')}<span>Once created, a sample menu, email and homepage are generated from these settings – about 20 seconds.</span></div>`}
function bkPaint(){$('#bkStepper').innerHTML=BK_STEPS.map((t,i)=>`<button class="select-card ${i===BK.step?'on':''}" style="display:flex;gap:10px;align-items:center;width:100%;margin-bottom:6px;padding:10px 12px" data-action="ai-bk-step" data-i="${i}"><span style="width:26px;height:26px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:12px;${i<BK.step?'background:var(--brand-tint);color:var(--brand-700)':i===BK.step?'background:var(--brand-700);color:#fff':'border:2px solid var(--border-input);color:var(--muted)'}">${i<BK.step?'✓':i+1}</span><strong style="color:${i===BK.step?'var(--brand-900)':'var(--ink)'}">${t}</strong></button>`).join('');
  $('#bkBody').innerHTML=`<div class="eyebrow" style="margin-bottom:6px">Step ${BK.step+1} of 6</div>`+bkStep();
  $('#bkFoot').innerHTML=`${BK.step?`<button class="btn secondary" data-action="ai-bk-back">Back</button>`:`<button class="btn secondary" data-href="brand-kit">Cancel</button>`}<span class="muted" style="flex:1;text-align:center">Step ${BK.step+1} of 6</span>${BK.step===5?`<button class="btn ai-btn" data-action="ai-bk-create">${ic('sparkle','sm')}Create kit</button>`:`<button class="btn primary" data-action="ai-bk-next">Continue</button>`}`}
App.route('brand-kit-scratch',()=>{if(!BK)bkNew();return `
  <a href="#brand-kit" class="btn ghost" style="padding:0;margin-bottom:12px">${ic('back','sm')}Back to brand kit</a>
  <div class="page-head"><div><h1>Build from scratch</h1><p class="sub">Six short steps – name, logo, colours, type and mood. You can change anything later.</p></div></div>
  <div style="display:grid;grid-template-columns:260px minmax(0,1fr);gap:20px;align-items:start">
   <div class="card pad"><div class="eyebrow" style="margin-bottom:10px">Build from scratch</div><div id="bkStepper"></div></div>
   <div class="card"><div id="bkBody" style="padding:24px"></div><div id="bkFoot" style="display:flex;align-items:center;gap:10px;padding:14px 24px;border-top:1px solid var(--border);background:var(--page);border-radius:0 0 14px 14px"></div></div></div>`},{nav:'brand-kit'});
App.after('brand-kit-scratch',()=>bkPaint());
A('ai-bk-step',el=>{BK.step=+el.dataset.i;bkPaint()});
A('ai-bk-next',()=>{if(BK.step===0&&!BK.name.trim())return toast('Enter your restaurant name');BK.step=Math.min(5,BK.step+1);bkPaint();scrollTo(0,0)});
A('ai-bk-back',()=>{BK.step=Math.max(0,BK.step-1);bkPaint()});
A('ai-bk-f',el=>{BK[el.dataset.k]=el.value});
A('ai-bk-logo',el=>{if(el.files[0]){BK.logo=el.files[0].name;bkPaint();toast('Logo added')}});
A('ai-bk-logo-rm',()=>{BK.logo=null;bkPaint()});
A('ai-bk-preset',el=>{const p=PRESETS[el.dataset.p];['primary','secondary','accent','background','surface','ink'].forEach((k,i)=>BK.colors[k]=p[i]);BK.preset=el.dataset.p;bkPaint()});
A('ai-bk-color',el=>{const k=el.dataset.k;BK.colors[k]=el.value;BK.preset='Custom';$('#sw-'+k).style.background=el.value;$('#hx-'+k).textContent=el.value.toUpperCase();$('#bkSample').innerHTML=bkSample();
  const cr=contrast(BK.colors.ink,BK.colors.background),e=$('#bkCr');if(e){e.textContent=`${cr>=7?'Easy to read':cr>=4.5?'Readable':'Hard to read'} · ${cr.toFixed(1)}:1`;e.style.color=cr>=4.5?'var(--ok)':'var(--bad)'}
  $$('[data-action="ai-bk-preset"]').forEach(b=>b.classList.remove('on'))});
A('ai-bk-type',el=>{BK.type=+el.dataset.i});
A('ai-bk-mood',el=>{BK.mood=el.dataset.m});
A('ai-bk-create',()=>{modal({title:'Creating your brand kit',body:`<p style="margin-top:0">Generating a sample menu, email and homepage from your settings…</p><div class="progress"><i id="bkc" style="width:5%;transition:width 1.4s"></i></div>`});setTimeout(()=>{const b=$('#bkc');if(b)b.style.width='100%'},40);
  setTimeout(()=>{ST.brandKit={name:BK.name,tagline:BK.tagline,cuisine:BK.cuisine,concept:BK.concept,logo:BK.logo,colors:{...BK.colors},preset:BK.preset,type:BK.type,typeName:TYPES[BK.type][2],mood:BK.mood};closeModal();BK=null;App.go('brand-kit');toast('Brand kit created')},1500)});

/* =====================================================================
   4.3 AI MEDIA STUDIO
   ===================================================================== */
const STYLE_CATS=[['Premium & Luxury',['Michelin Fine Dining','Wine Bar Sophistication','Candlelit Romance']],['Casual & Modern',['Clean Contemporary','Scandi Minimalist','Modern Brunch Aesthetic','Industrial Loft','Bright Brunch Table']],
 ['Atmospheric & Moody',['Moody Rustic Gastropub','Dark & Dramatic Editorial','Cinematic Night Urban','Dark Academia Cafe','Cottagecore Cozy']],['Cuisine-Specific',['Indian Restaurant Warmth','Middle Eastern Souk','Modern Asian Fusion','Mexican Cantina Vibrant','French Bistro Classic','Mediterranean Coastal','Japanese Izakaya','Authentic Italian Trattoria']],
 ['Beverage-Focused',['Craft Cocktail Bar','Beer Garden Casual','Tropical Tiki Bar','Coffee Shop Artisan','Classic Pub Grub']],['Specialized Venue',['Patisserie Window Display','Artisan Bakery Rustic','BBQ Smokehouse','Seafood Market Fresh','Steakhouse Classic','Food Truck Urban Street','Ice Cream Parlor Nostalgic','Dessert Bar Whimsical','Rustic Farm-to-Table']],
 ['Trending & Contemporary',['Neon Cyberpunk','Maximalist Eclectic','Instagram Food Blogger','In Hand at Your Storefront','Street Food Market']],['Seasonal & Occasion',['Holiday Celebration','Spring Garden Fresh','Winter Lodge Cozy','Autumn Harvest','Summer Rooftop']],
 ['Technical Photography',['Pure Enhance','Macro Detail Focus','Hero Product Spotlight','Action Shot Dynamic','Lifestyle Hand Model','Overhead Grid Layout']]];
const STYLE_SUB={'Pure Enhance':'Enhance only – no restyle','In Hand at Your Storefront':'Needs venue photos','Macro Detail Focus':'Extreme close-up texture','Michelin Fine Dining':'Refined plating, soft light','Hero Product Spotlight':'Single dish, studio light'};
const STYLES=STYLE_CATS.flatMap(([cat,names])=>names.map((n,i)=>({name:n,cat,credits:n==='Pure Enhance'?5:7,was:n==='Pure Enhance'?15:0,badge:['Pure Enhance','Michelin Fine Dining','Modern Brunch Aesthetic','Instagram Food Blogger'].includes(n)?'POPULAR':(['In Hand at Your Storefront','Neon Cyberpunk','Summer Rooftop','Middle Eastern Souk'].includes(n)?'NEW':''),sub:STYLE_SUB[n]||cat.replace(/ &.*/,'')+' look'})));
const VIDEO_TPL=[['Cinematic Fly Around',110,'NEW'],['Cinematic Fly-Through',110,'NEW'],['Full Table',50,'POPULAR'],['Ingredient Reveal',60,'POPULAR'],['Restaurant Ad',300,''],['Beautiful Table',520,''],['Make It Shine',180,''],['Delicious Close-Up',100,''],['Every Angle',60,'']];
const RATIOS=[['1:1','Square','POPULAR','Best for menu item photos, Instagram posts, Facebook posts and delivery apps.'],['4:5','Portrait','','Best for Instagram feed posts – takes up more of the screen.'],['9:16','Tall','','Best for Stories, Reels and TikTok.'],['16:9','Wide','','Best for websites, banners and YouTube.']];
const ANGLES=[['From above','Overhead · 90°'],["Diner's view",'Angled · 45°'],['Eye level','Side view · 0–20°']];
const QUICK=['Add steam','Add droplets','More vibrant','Brighter lighting','Add garnish','Refine plating'];
const CATS_ITEM=['Dish','Drink','Dessert','Side','Appetizer','Salad','Soup','Snack'];
let MS={media:'image',mode:'enhance',style:null,image:null,instr:'',angle:null,ratio:'1:1',vstyle:null,item:'',cat:null,result:null,history:[]};
const msReset=()=>{Object.assign(MS,{style:null,image:null,instr:'',angle:null,ratio:'1:1',vstyle:null,item:'',cat:null,result:null})};
function msPickTile(label,val,act,icon,sub){return `<button class="select-card ${val?'on':''}" style="width:100%;display:flex;gap:12px;align-items:center" data-action="${act}">${val?tile(val,48,'','width:48px;flex:none'):`<span class="itile">${ic(icon)}</span>`}<div style="flex:1;text-align:left"><strong style="color:var(--ink)">${val?esc(val):label}</strong><div class="help" style="margin:0">${val?'Tap to change':sub}</div></div>${ic('chev','sm')}</button>`}
function msRatio(){return `${numLbl(MS.mode==='create'||MS.media==='video'?(MS.media==='video'?3:5):5,'Where will you use it?','This sets the image shape. Not sure? Square works almost everywhere.')}<div class="grid g4" style="gap:8px">${RATIOS.map(([r,n,b])=>`<button class="select-card ${MS.ratio===r?'on':''}" data-action="ai-ms-ratio" data-r="${r}" style="text-align:center;padding:12px 6px"><div style="margin:0 auto 6px;border:2px solid currentColor;color:var(--brand-700);border-radius:4px;width:${r==='16:9'?36:r==='9:16'?18:r==='4:5'?24:28}px;height:${r==='16:9'?20:r==='9:16'?32:r==='4:5'?30:28}px"></div><strong style="color:var(--ink);font-size:13px">${n}</strong><div class="help" style="margin:0">${r}</div>${b?`<span class="pill" style="height:18px;font-size:10px;margin-top:4px">${b}</span>`:''}</button>`).join('')}</div><div class="help" id="msBest">${RATIOS.find(x=>x[0]===MS.ratio)[3]}</div>`}
function msLeft(){
  if(MS.media==='video')return `${stepLbl(1,'Select Style')}${msPickTile('Select Style',MS.vstyle,'ai-ms-vstyle','video','Choose a video template')}
   ${stepLbl(2,'Select Image')}${msPickTile('Select Image',MS.image,'ai-ms-image','img','Menu or Upload')}${msRatio()}
   <div style="display:flex;gap:10px;margin-top:22px"><button class="btn ai-btn" style="flex:1;height:46px" data-action="ai-ms-go" ${MS.vstyle&&MS.image?'':'disabled'}>${ic('sparkle','sm')}Generate Video${MS.vstyle?` · ${ST.freeVideoUsed?VIDEO_TPL.find(v=>v[0]===MS.vstyle)[1]+' credits':'Free'}`:''}</button><button class="btn secondary" style="height:46px" data-action="ai-ms-reset">${ic('refresh','sm')}Reset</button></div>
   <div class="help">Your first video is on us.</div>`;
  const tail=`${numLbl(3,'Custom instructions (optional)','Add finishing touches like steam, garnish or brighter lighting')}
   ${UI.textarea({id:'msInstr',value:MS.instr,rows:3,placeholder:'Write your own, e.g. focus on the main item, softer shadows, warmer tones',attrs:'data-input="ai-ms-instr"'})}
   <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">${QUICK.map(q=>`<button class="chip-btn" data-action="ai-ms-quick" data-q="${q}">${ic('plus','sm')}${q}</button>`).join('')}</div><div class="help">Pick quick adds, write your own, or combine both.</div>
   ${numLbl(4,'Which angle shows it best?')}<div class="grid g3" style="gap:8px">${ANGLES.map(([a,s])=>`<button class="select-card ${MS.angle===a?'on':''}" data-action="ai-ms-angle" data-a="${esc(a)}" style="text-align:center;padding:12px"><strong style="color:var(--ink)">${a}</strong><div class="help" style="margin:2px 0 0">${s}</div></button>`).join('')}</div>${msRatio()}`;
  if(MS.mode==='create')return `${numLbl(1,'Item Name <span class="req">*</span>')}${UI.input({id:'msItem',value:MS.item,placeholder:'e.g. Pistachio French Toast',attrs:'data-input="ai-ms-item"'})}
   ${numLbl(2,'Category (optional)')}<div style="display:flex;gap:6px;flex-wrap:wrap">${CATS_ITEM.map(c=>`<button class="chip-btn ${MS.cat===c?'on':''}" data-action="ai-ms-cat" data-c="${c}">${c}</button>`).join('')}</div>${tail}
   <div style="display:flex;gap:10px;margin-top:22px"><button class="btn ai-btn" style="flex:1;height:46px" id="msGo" data-action="ai-ms-go" ${MS.item.trim()?'':'disabled'}>${ic('sparkle','sm')}Create Image · 3 credits</button><button class="btn secondary" style="height:46px" data-action="ai-ms-reset">${ic('refresh','sm')}Reset</button></div>`;
  const st=MS.style&&STYLES.find(s=>s.name===MS.style);
  return `${stepLbl(1,'Select Style')}${msPickTile('Select Style',MS.style,'ai-ms-style','palette','51 styles to choose from')}
   ${stepLbl(2,'Select Image')}${msPickTile('Select Image',MS.image,'ai-ms-image','img','Menu or Upload')}${tail}
   <div style="display:flex;gap:10px;margin-top:22px"><button class="btn ai-btn" style="flex:1;height:46px" data-action="ai-ms-go" ${MS.style&&MS.image?'':'disabled'}>${ic('sparkle','sm')}Enhance${st?' · '+st.credits+' credits':''}</button><button class="btn secondary" style="height:46px" data-action="ai-ms-reset">${ic('refresh','sm')}Reset</button></div>`}
function msRight(){const r=MS.ratio.split(':');const ar=`${r[0]}/${r[1]}`;const vid=MS.media==='video';const cr=MS.mode==='create';
  const ph=`<div style="aspect-ratio:${ar};max-height:420px;margin:0 auto;border:2px dashed var(--border-input);border-radius:14px;display:grid;place-items:center;text-align:center;padding:20px;background:var(--page)">${MS.result?`<div class="thumbbg" style="${grad(hash(MS.result.name))};position:absolute"></div>`:''}<div><span class="itile" style="margin:0 auto 10px">${ic(vid?'video':'img')}</span><strong style="color:var(--ink)">${vid?'Your video will appear here':cr?'Your created image will appear here':'Your enhanced image will appear here'}</strong><div class="help">${vid?'Select an image and style, then click Generate':cr?'Fill in the details and click Create to generate':'Upload an image and click Enhance to start'}</div><span class="pill grey" style="margin-top:8px">${MS.ratio}</span></div></div>`;
  const res=MS.result?`<div class="thumbbg" style="${grad(hash(MS.result.name))};aspect-ratio:${ar};max-height:420px;margin:0 auto;border-radius:14px;display:flex;align-items:flex-end;padding:16px;color:#fff">${vid?`<span style="position:absolute;margin:auto">${ic('play')}</span>`:''}<div><strong style="font-size:18px">${esc(MS.result.name)}</strong><div style="opacity:.9">${esc(MS.result.style)}</div></div></div><div style="display:flex;gap:8px;justify-content:center;margin-top:12px"><button class="btn secondary sm" data-action="download">${ic('download','sm')}Download</button><button class="btn secondary sm" data-href="ai-media-library">${ic('img','sm')}Open in library</button></div>`:ph;
  return `<div class="card pad">${vid?`<h3 style="margin-bottom:12px">Generated Video</h3>`:UI.tabs([{key:'r',label:'Result'},{key:'b',label:'Before / After'}],'r','msres')}
   ${UI.panel('msres','r',res,'r')}${vid?'':UI.panel('msres','b',`<div class="grid g2" style="gap:10px"><div><div class="help" style="margin-top:0">Before</div>${MS.image?tile(MS.image+'b',200,`<small>${esc(MS.image)}</small>`,'filter:saturate(.4) brightness(.85)'):'<div class="empty">No image yet</div>'}</div><div><div class="help" style="margin-top:0">After</div>${MS.result?tile(MS.result.name,200,'<small>Enhanced</small>'):'<div class="empty">Not enhanced yet</div>'}</div></div>`,'r')}
   ${vid||cr?'':`<p class="help" style="text-align:center">Best for menu item photos, Instagram posts, Facebook posts and delivery apps.</p>`}</div>
   <div class="card pad" style="margin-top:16px"><h3 style="margin-bottom:10px">Recent History</h3>${MS.history.length?`<div class="grid g4" style="gap:8px">${MS.history.map(h=>tile(h.name,80,`<small>${esc(h.name)}</small>`)).join('')}</div>`:UI.empty('history','No history yet')}</div>`}
App.route('ai-media-studio',()=>`
  ${UI.pageHead({title:'AI Media Studio',sub:'Transform your food photos with AI-powered styles and video',tutorial:true})}
  <div class="tabs">${[['image','Image',''],['video','Video','<span class="tag-new">NEW</span>'],['3d','3D','<span class="tag-soon">SOON</span>']].map(([k,l,b])=>`<button class="${MS.media===k?'on':''}" ${k==='3d'?'disabled':`data-action="ai-ms-media" data-m="${k}"`}>${ic(k==='image'?'img':k==='video'?'video':'cube','sm')} ${l}${b}</button>`).join('')}</div>
  <div class="split" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr)">
   <div class="card pad">${MS.media==='image'?`<div class="seg" style="margin-bottom:6px"><button class="${MS.mode==='enhance'?'on':''}" data-action="ai-ms-mode" data-m="enhance">${ic('wand','sm')} Enhance</button><button class="${MS.mode==='create'?'on':''}" data-action="ai-ms-mode" data-m="create">${ic('sparkle','sm')} Create</button></div>`:''}<div id="msLeft">${msLeft()}</div></div>
   <div id="msRight">${msRight()}</div></div>`,{nav:'ai-media-studio'});
const msPaint=()=>{$('#msLeft').innerHTML=msLeft();$('#msRight').innerHTML=msRight()};
A('ai-ms-media',el=>{MS.media=el.dataset.m;MS.result=null;App.render()});
A('ai-ms-mode',el=>{MS.mode=el.dataset.m;MS.result=null;App.render()});
A('ai-ms-instr',el=>{MS.instr=el.value});
A('ai-ms-item',el=>{MS.item=el.value;const b=$('#msGo');if(b)b.disabled=!el.value.trim()});
A('ai-ms-cat',el=>{MS.cat=MS.cat===el.dataset.c?null:el.dataset.c;msPaint()});
A('ai-ms-quick',el=>{const t=$('#msInstr');MS.instr=(t.value.trim()?t.value.trim().replace(/[,.]?$/,', '):'')+el.dataset.q.toLowerCase();t.value=MS.instr;el.classList.add('on')});
A('ai-ms-angle',el=>{MS.angle=el.dataset.a;msPaint()});
A('ai-ms-ratio',el=>{MS.ratio=el.dataset.r;msPaint()});
A('ai-ms-reset',()=>{msReset();msPaint();toast('Reset')});
/* style modal */
let styleCat='All Styles',styleQ='';
function styleGrid(){const list=STYLES.filter(s=>(styleCat==='All Styles'||s.cat===styleCat)&&s.name.toLowerCase().includes(styleQ.toLowerCase()));
  return list.length?`<div class="grid g4" style="gap:12px">${list.map(s=>`<button class="select-card ${MS.style===s.name?'on':''}" style="padding:0;overflow:hidden;position:relative" data-action="ai-ms-pickstyle" data-n="${esc(s.name)}">${tile(s.name,110,`<span style="display:flex;gap:4px;position:absolute;top:8px;left:8px">${s.badge?`<span class="pill" style="height:18px;font-size:10px">${s.badge}</span>`:''}</span><small style="background:rgba(0,0,0,.35);border-radius:6px;padding:1px 6px">≈1 min</small>`,'border-radius:0;position:relative')}
   <div style="padding:10px"><div style="display:flex;justify-content:space-between;align-items:center"><strong style="color:var(--ink);font-size:13px">${esc(s.name)}</strong><span title="${esc(s.sub)}" class="muted">${ic('info','sm')}</span></div><div class="help" style="margin:2px 0 4px">${esc(s.sub)}</div><span class="pill grey" style="height:20px">${ic('coin','sm')}${s.credits}${s.was?` <s class="muted">${s.was}</s> <b style="color:var(--ok)">-67%</b>`:''}</span></div></button>`).join('')}</div>`:UI.empty('search','No styles match your search')}
A('ai-ms-style',()=>{styleCat='All Styles';styleQ='';modal({title:`Select Style <span class="muted" style="font-weight:500;font-size:14px">· ${STYLES.length} styles</span>`,wide:true,body:`${UI.searchBox('Search styles...','data-input="ai-ms-styleq" style="flex:1"')}
  <div style="display:flex;gap:6px;flex-wrap:wrap;margin:12px 0 14px" id="styleCats">${[['All Styles',STYLES.length],...STYLE_CATS.map(([c,n])=>[c,n.length])].map(([c,n])=>`<button class="chip-btn ${c===styleCat?'on':''}" data-action="ai-ms-stylecat" data-c="${esc(c)}">${c} <span class="muted">${n}</span></button>`).join('')}</div><div id="styleGrid" style="max-height:56vh;overflow:auto">${styleGrid()}</div>`});$('#modal').style.maxWidth='980px'});
A('ai-ms-styleq',el=>{styleQ=el.value;$('#styleGrid').innerHTML=styleGrid()});
A('ai-ms-stylecat',el=>{styleCat=el.dataset.c;$$('#styleCats .chip-btn').forEach(c=>c.classList.toggle('on',c===el));$('#styleGrid').innerHTML=styleGrid()});
A('ai-ms-pickstyle',el=>{MS.style=el.dataset.n;closeModal();msPaint();toast(MS.style+' selected')});
A('ai-ms-vstyle',()=>modal({title:'Select Style',wide:true,body:`<div class="help" style="margin-top:0">Your first video is on us.</div><div class="grid g3" style="gap:12px;margin-top:10px">${VIDEO_TPL.map(([n,c,b])=>`<button class="select-card ${MS.vstyle===n?'on':''}" style="padding:0;overflow:hidden" data-action="ai-ms-pickv" data-n="${esc(n)}">${tile(n,160,`<span style="position:absolute;top:8px;left:8px;display:flex;gap:4px"><span class="pill" style="height:18px;font-size:10px">FREE</span>${b?`<span class="pill" style="height:18px;font-size:10px">${b}</span>`:''}</span>`,'border-radius:0;position:relative')}<div style="padding:10px"><strong style="color:var(--ink)">${n}</strong><div class="help" style="margin:2px 0 0">0 credits <s>${c}</s> · first video only</div></div></button>`).join('')}</div>`}));
A('ai-ms-pickv',el=>{MS.vstyle=el.dataset.n;closeModal();msPaint()});
/* image picker (shared with marketing) */
let imgCb='ms',imgFilter='all',imgQ='';
function imgGrid(){const m=ST.menus[0];let its=allItems().filter(i=>i.photo);if(imgFilter==='rec')its=its.filter(i=>i.score<80);its=its.filter(i=>i.name.toLowerCase().includes(imgQ.toLowerCase()));
  return `<div class="help" style="font-weight:600;color:var(--ink);margin:0 0 10px">${esc(m.name)} (${its.length} items)</div>${its.length?`<div class="grid g4" style="gap:10px">${its.map(i=>`<button class="select-card" style="padding:0;overflow:hidden" data-action="ai-pickimg" data-n="${esc(i.name)}">${tile(i.name,90,'','border-radius:0')}<div style="padding:8px;font-size:12px;font-weight:600;color:var(--ink)">${esc(i.name)}</div></button>`).join('')}</div>`:UI.empty('search','No items found')}`}
function openImagePicker(cb){imgCb=cb;imgFilter='all';imgQ='';modal({title:'Select Image',wide:true,body:`${UI.tabs([{key:'m',label:'Menu Items'},{key:'u',label:'Upload'},{key:'h',label:'History'}],'m','imgp')}
  ${UI.panel('imgp','m',`<div class="toolbar"><div class="seg"><button class="on" data-action="ai-img-filter" data-f="all">All Items</button><button data-action="ai-img-filter" data-f="rec">Recommended</button></div>${UI.searchBox('Search menu items...','data-input="ai-img-q" style="flex:1"')}</div><div id="imgGrid" style="max-height:50vh;overflow:auto">${imgGrid()}</div>`,'m')}
  ${UI.panel('imgp','u',`<label class="upload" style="padding:40px">${ic('upload')}<div style="font-weight:600;margin-top:6px">Click or drag an image to upload</div><div class="help">JPG, PNG, WEBP or HEIC · up to 10MB</div><input type="file" accept="image/*" style="display:none" data-change="ai-img-upload"></label>`,'m')}
  ${UI.panel('imgp','h',ST.media.length?`<div class="grid g4" style="gap:10px">${ST.media.map(m=>`<button class="select-card" style="padding:0;overflow:hidden" data-action="ai-pickimg" data-n="${esc(m.name)}">${tile(m.name,90,'','border-radius:0')}<div style="padding:8px;font-size:12px">${esc(m.name)}</div></button>`).join('')}</div>`:UI.empty('history','No history yet'),'m')}`});$('#modal').style.maxWidth='900px'}
App.openImagePicker=openImagePicker;
A('ai-ms-image',()=>openImagePicker('ms'));
A('ai-img-filter',el=>{imgFilter=el.dataset.f;el.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b===el));$('#imgGrid').innerHTML=imgGrid()});
A('ai-img-q',el=>{imgQ=el.value;$('#imgGrid').innerHTML=imgGrid()});
function gotImage(n){closeModal();if(imgCb==='ms'){MS.image=n;msPaint()}else{MC.photo=n;mcPaint()}toast('Image selected')}
A('ai-pickimg',el=>gotImage(el.dataset.n));
A('ai-img-upload',el=>{if(el.files[0])gotImage(el.files[0].name)});
/* generate */
A('ai-ms-go',()=>{const done=(name,style,type)=>{MS.result={name,style};MS.history.unshift({name});ST.media.unshift({name,type,src:'AI Media Studio',credits:0,date:'Today'});msPaint();toast(type==='Video'?'Video generated':'Image ready')};
  if(MS.media==='video'){const t=VIDEO_TPL.find(v=>v[0]===MS.vstyle);if(!ST.freeVideoUsed){ST.freeVideoUsed=true;toast('Generating your free video…');setTimeout(()=>done(MS.image+' – '+t[0],t[0],'Video'),900)}else spend(t[1],()=>done(MS.image+' – '+t[0],t[0],'Video'));return}
  if(MS.mode==='create')return spend(3,()=>done(MS.item,MS.cat||'Dish','Image'));
  const s=STYLES.find(x=>x.name===MS.style);spend(s.credits,()=>done(MS.image,s.name,'Image'))});

