const MK_VIDEO=[['Opening Hours',10,'motion',''],['Slow Reveal',110,'food','NEW'],['Launch Pad',80,'food','NEW'],['Delivery Dash',80,'food','NEW'],['UGC Venue Visit',150,'ugc','NEW'],['Smash Entry',50,'food','NEW'],['Phone POV',30,'food','NEW'],['Comfort Dive',80,'food','NEW'],['Last-Second Catch',40,'food','NEW'],['Tiny Town',70,'cgi','NEW'],['Cut-Away Reveal',90,'food','NEW'],['Sauce Pour',50,'food','NEW'],['Motion Graphic Poster',20,'food','NEW'],['Gentle Drop',130,'food','NEW'],['CGI Product Video',50,'cgi','POPULAR'],['UGC Product Review',100,'ugc','NEW']];
const IMG_BASE={agnostic:['Come Say Hi (Story)'],seasonal:['Festive Table'],dessert:['Sweet Tooth','Sugar Rush'],
 beverage:['Pour Decisions','Cheers Card','Sip & Slide','Latte Love','Cocktail Hour','Fresh Squeeze','Coffee Clock','Bubbles Up','Iced & Easy','Happy Hour Flyer','Tea Time','Shake It','Neon Sip','Morning Brew','Mocktail Mood','Bottle Spotlight'],
 food:["Table's Saved (Story)",'Receipt Deal','Pixel Pair','Fill the Blank','Chef\'s Pick','Daily Special','Plate Up','New on the Menu','Bestseller Badge','Combo Card','Weekend Brunch','Lunch Rush','Dinner Date','Price Drop','Grid of Four','Split Screen','Polaroid Stack','Magazine Cover','Menu Board','Hand-Drawn Notes','Big Bold Price','Street Poster','Minimal Frame','Ticket Stub','Recipe Card','Order Now','Delivery Ready','Pick-Up Promo','Family Feast','Kids Eat Free','Loyalty Stamp','Countdown Deal','Flash Sale','Two for One','Spicy Alert','Vegan Pick','Comfort Food','Late Night Bites','Sunday Roast','Breakfast Club','Taste Test','Review Quote','Behind the Pass']};
